@CrossOrigin
@RestController
@RequestMapping("/MatterQuery")
public class MatterQueryRestController extends BaseSpringRestController {
	
	public MatterQueryRestController( MatterService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Matter using a UUID
     * @param		UUID matterId
     * @return		Matter
     */    
    @GetMapping("/load")
    public Matter load( @RequestParam(required=true) UUID matterId ) {
    	Matter entity = null;

    	try {  
    		entity = service.getMatter( new MatterFetchOneSummary( matterId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Matter using Id " + matterId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Matter business objects
     * @return		Set<Matter>
     */
    @GetMapping("/")
    public List<Matter> loadAll() {                
    	List<Matter> matterList = null;
        
    	try {
            // load the Matter
            matterList = service.getAllMatter();
            
            if ( matterList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Matters" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Matters ", exc );
        	return null;
        }

        return matterList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Matter matter = null;
    protected MatterService service = null;
    private static final Logger LOGGER = Logger.getLogger(MatterQueryRestController.class.getName());
    
}
